285→    private void DrawTriStateCheckbox(string prefix, EntitySnapshot snapshot, ComponentSnapshot comp = null)
286→    {
287→        var leafPaths = GetLeafPaths(prefix, snapshot, comp);
288→        var state = _watcherState.GetPrefixState(prefix, leafPaths);
289→
