321→    private static List<string> GetLeafPaths(string prefix, EntitySnapshot snapshot, ComponentSnapshot comp)
322→    {
323→        var paths = new List<string>();
324→        if (comp != null)
325→        {
326→            foreach (var field in comp.Fields)
