303→            var midY = (min.Y + max.Y) * 0.5f;
304→            var dashColor = ImGui.GetColorU32(ImGuiCol.CheckMark);
305→            drawList.AddLine(
306→                new Vector2(min.X + 4, midY),
307→                new Vector2(max.X - 4, midY),
308→                dashColor, 2f);
309→        }
310→    }
