321→    private static List<string> GetLeafPaths(string prefix, EntitySnapshot snapshot, ComponentSnapshot comp)
322→    {
323→        var paths = new List<string>();
324→        if (comp != null)
325→        {
326→            foreach (var field in comp.Fields)
327→                paths.Add($"{prefix}/{field.Name}");
328→            foreach (var prop in comp.Properties)
329→                paths.Add($"{prefix}/{prop.Name}");
330→        }
331→        else
332→        {
333→            foreach (var c in snapshot.Components)
334→            {
335→                var compPath = $"{prefix}/{c.TypeName}";
336→                foreach (var field in c.Fields)
337→                    paths.Add($"{compPath}/{field.Name}");
338→                foreach (var prop in c.Properties)
339→                    paths.Add($"{compPath}/{prop.Name}");
340→            }
341→        }
342→        return paths;
343→    }
