101→        {
102→            "PixelPerfect" => ViewportManager.ScalingMode.PixelPerfect,
103→            "Smooth" => ViewportManager.ScalingMode.Smooth,
104→            _ => ViewportManager.ScalingMode.KeepAspectRatio
105→        };
