107→        GraphicsDevice.RasterizerState = RasterizerState.CullCounterClockwise;
108→        GraphicsDevice.BlendState = BlendState.AlphaBlend;
109→
110→        _spriteBatch = new(GraphicsDevice);
111→        _runner = new(1);
112→        _screenController = new(this, _runner, _viewportManager, _camera, _spriteBatch, Content);
113→        _camera.Zoom = _settings.CameraZoom;
114→        _camera.Position = Vector2.Zero;
115→
116→#if DEBUG
117→        if (!_headless)
118→        {
