101→    private void CreateTreadmill()
102→    {
103→        // Invisible collider for physics
104→        var collider = _world.CreateEntity();
105→        collider.Set(new EntityInfo("Wall"));
106→        collider.Set(new Transform(new Vector2(0, RunnerConstants.TreadmillY)));
107→        collider.Set(new BoxCollider(
108→            new Rectangle(0, 0, (int)RunnerConstants.TreadmillTotalWidth, (int)RunnerConstants.TreadmillSegmentHeight),
109→            passive: true));
110→        collider.Set(new RigidBody(isKinematic: true, gravityActive: false));
111→
112→        // Cosmetic segments — top row (scrolls left)
113→        for (int i = 0; i < RunnerConstants.TreadmillSegmentCount; i++)
114→        {
115→            CreateTreadmillSegment(i, RunnerConstants.TreadmillY, RunnerConstants.TreadmillColor, isTopRow: true);
116→        }
117→
118→        // Cosmetic segments — bottom row (scrolls right)
119→        var bottomY = RunnerConstants.TreadmillY + RunnerConstants.TreadmillSegmentHeight + RunnerConstants.BottomRowGap;
120→        for (int i = 0; i < RunnerConstants.TreadmillSegmentCount; i++)
121→        {
122→            CreateTreadmillSegment(i, bottomY, RunnerConstants.TreadmillBottomColor, isTopRow: false);
123→        }
124→    }
