225→    private static CollisionMessage CreateRunnerCollision(
226→        Entity entity, Entity target, Vector2 contactPoint, Vector2 contactNormal, float contactTime, float penetrationDepth, int layer)
227→    {
228→        var entityType = entity.Get<EntityInfo>().Type;
229→        var targetType = target.Get<EntityInfo>().Type;
230→        var type = (entityType, targetType) switch
231→        {
232→            ("Player", "Collectible") => CollisionType.Collectible,
233→            ("Player", "Obstacle") => CollisionType.Damage,
234→            _ => CollisionType.Physics
235→        };
236→        return new CollisionMessage(entity, target, contactPoint, contactNormal, contactTime, penetrationDepth, layer, type);
237→    }
