**Entity Introspection (lines 68-127):**

Uses **reflection-based introspection** through `ComponentIntrospector`:

```csharp
private void RefreshEntitySnapshots(World world)
{
    _allSnapshots.Clear();
    _rootSnapshots.Clear();

    foreach (var entity in world.GetEntities().AsEnumerable())
    {
        if (!entity.IsAlive) continue;
        _totalEntityCount++;

        // Extract EntityInfo if present
        string displayName;
        if (entity.Has<EntityInfo>())
        {
            var info = entity.Get<EntityInfo>();
            displayName = $"{info.Name} ({info.Type}) #{entity.GetHashCode():X}";
        }
        else
        {
            displayName = $"Entity #{entity.GetHashCode():X}";
        }

        // Build component list via reflection
        _allSnapshots[entity] = new EntitySnapshot
        {
            Entity = entity,
            DisplayName = displayName,
            Components = _introspector.ReadEntity(entity)
        };
    }

    // Read hierarchy from world resource (set by HierarchySystem)
    var hierarchy = world.Has<EntityHierarchy>() ? world.Get<EntityHierarchy>() : null;

    if (hierarchy != null)
    {
        // Wire up parent-child tree from EntityHierarchy
        foreach (var (entity, snapshot) in _allSnapshots)
        {
            var parent = hierarchy.GetParent(entity);
            if (parent.HasValue && _allSnapshots.TryGetValue(parent.Value, out var parentSnapshot))
            {
                parentSnapshot.Children.Add(snapshot);
            }
            else
            {
                _rootSnapshots.Add(snapshot);
            }
        }
    }
    else
    {
        // No hierarchy available — flat list
        _rootSnapshots.AddRange(_allSnapshots.Values);
    }
}
```

**Component Introspection via `ComponentIntrospector`:**

Location: `/Users/rodrigooliveira/git/roo-oliv/monodreams/MonoDreams.Examples/Inspector/ComponentIntrospector.cs`

Implements DefaultEcs's `IComponentReader` interface:

```csharp
public class ComponentIntrospector : IComponentReader
{
    private readonly List<ComponentSnapshot> _accumulator = new();
    private static readonly ConcurrentDictionary<Type, FieldInfo[]> FieldCache = new();
    private static readonly ConcurrentDictionary<Type, PropertyInfo[]> PropertyCache = new();

    public void OnRead<T>(in T component, in Entity entity)
    {
        var type = typeof(T);
        var fields = FieldCache.GetOrAdd(type, t =>
            t.GetFields(BindingFlags.Public | BindingFlags.Instance));
        var properties = PropertyCache.GetOrAdd(type, t =>
            t.GetProperties(BindingFlags.Public | BindingFlags.Instance)
                .Where(p => p.CanRead && p.GetIndexParameters().Length == 0)
                .ToArray());

        _accumulator.Add(new ComponentSnapshot
        {
            TypeName = type.Name,
            Type = type,
            BoxedValue = component,
            Fields = fields,
            Properties = properties
        });
    }

    public List<ComponentSnapshot> ReadEntity(Entity entity)
    {
        _accumulator.Clear();
        entity.ReadAllComponents(this);
        return new List<ComponentSnapshot>(_accumulator);
    }
}
```

**Key points:**
- Caches reflection data per type for performance
- Only exposes **public instance fields and readable properties** (no parameters)
- Boxes component values to display them generically

