285→    private void DrawTriStateCheckbox(string prefix, EntitySnapshot snapshot, ComponentSnapshot comp = null)
286→    {
287→        var leafPaths = GetLeafPaths(prefix, snapshot, comp);
288→        var state = _watcherState.GetPrefixState(prefix, leafPaths);
289→
290→        // ImGui doesn't have native tri-state: we render it manually
291→        var isChecked = state == true;
292→        if (ImGui.Checkbox($"##chk{prefix}", ref isChecked))
293→        {
294→            _watcherState.TogglePrefix(prefix, leafPaths);
295→        }
296→
297→        // Draw intermediate dash overlay
298→        if (state == null) // some checked
299→        {
300→            var drawList = ImGui.GetWindowDrawList();
301→            var min = ImGui.GetItemRectMin();
302→            var max = ImGui.GetItemRectMax();
303→            var midY = (min.Y + max.Y) * 0.5f;
304→            var dashColor = ImGui.GetColorU32(ImGuiCol.CheckMark);
305→            drawList.AddLine(
306→                new Vector2(min.X + 4, midY),
307→                new Vector2(max.X - 4, midY),
308→                dashColor, 2f);
309→        }
310→    }
