312→    private void DrawLeafCheckbox(string leafPath)
313→    {
314→        var isChecked = _watcherState.IsChecked(leafPath);
315→        if (ImGui.Checkbox($"##chk{leafPath}", ref isChecked))
316→        {
317→            _watcherState.ToggleLeaf(leafPath);
