345→    private void DrawWatchersPanel()
346→    {
347→        ImGui.Begin("Watchers");
348→
349→        if (!_watcherState.HasAnyChecked())
350→        {
351→            ImGui.TextDisabled("No items watched. Check items in World Hierarchy to pin them here.");
352→            ImGui.End();
353→            return;
354→        }
355→
356→        var i = 0;
357→        foreach (var snapshot in _allSnapshots.Values)
358→        {
359→            var entityPath = $"Entity:{snapshot.DisplayName}";
360→            var entityLeafPaths = GetLeafPaths(entityPath, snapshot, null);
361→
362→            // Skip entities with no checked leaves
363→            if (!_watcherState.HasAnyCheckedUnder(entityPath, entityLeafPaths))
364→            {
365→                i++;
366→                continue;
367→            }
368→
369→            DrawTriStateCheckbox(entityPath, snapshot);
370→            ImGui.SameLine();
371→
372→            if (ImGui.TreeNodeEx($"{snapshot.DisplayName}##we{i}", ImGuiTreeNodeFlags.DefaultOpen))
373→            {
374→                for (var c = 0; c < snapshot.Components.Count; c++)
375→                {
376→                    var comp = snapshot.Components[c];
377→                    var compPath = $"{entityPath}/{comp.TypeName}";
378→                    var compLeafPaths = GetLeafPaths(compPath, snapshot, comp);
379→
380→                    if (!_watcherState.HasAnyCheckedUnder(compPath, compLeafPaths))
381→                        continue;
382→
383→                    DrawTriStateCheckbox(compPath, snapshot, comp);
384→                    ImGui.SameLine();
385→
386→                    if (ImGui.TreeNodeEx($"{comp.TypeName}##we{i}c{c}", ImGuiTreeNodeFlags.DefaultOpen))
387→                    {
388→                        DrawWatcherComponentFields(comp, compPath);
389→                        ImGui.TreePop();
390→                    }
391→                }
392→                ImGui.TreePop();
393→            }
394→            i++;
395→        }
396→
397→        ImGui.End();
398→    }
