400→    private void DrawWatcherComponentFields(ComponentSnapshot comp, string compPath)
401→    {
402→        foreach (var field in comp.Fields)
403→        {
404→            var fieldPath = $"{compPath}/{field.Name}";
405→            if (!_watcherState.IsChecked(fieldPath)) continue;
406→
407→            DrawLeafCheckbox(fieldPath);
408→            ImGui.SameLine();
409→            var value = field.GetValue(comp.BoxedValue);
410→            DrawFormattedValue(field.Name, value, $"w{fieldPath}");
411→        }
412→        foreach (var prop in comp.Properties)
413→        {
414→            var fieldPath = $"{compPath}/{prop.Name}";
415→            if (!_watcherState.IsChecked(fieldPath)) continue;
416→
417→            DrawLeafCheckbox(fieldPath);
418→            ImGui.SameLine();
419→            try
420→            {
421→                var value = prop.GetValue(comp.BoxedValue);
422→                DrawFormattedValue(prop.Name, value, $"w{fieldPath}");
423→            }
424→            catch
425→            {
426→                ImGui.Text($"{prop.Name}: <error>");
427→            }
428→        }
429→    }
