 12→namespace MonoDreams.System.Debug;
 13→
 14→/// <summary>
 15→/// Per-frame debug visualization for BoxCollider and ConvexCollider shapes.
 16→/// Creates ephemeral mesh entities each frame that render colored outlines:
 17→/// red = active, green = passive, gray = disabled.
 18→/// </summary>
 19→public class ColliderDebugSystem : ISystem<GameState>
 20→{
 21→    public static bool Enabled = true;
 22→
 23→    private const float DebugLayerDepth = 1f;
 24→    private const float LineThickness = 0.5f;
 25→
 26→    private readonly World _world;
 27→    private readonly EntitySet _colliderEntities;
 28→    private readonly List<Entity> _debugEntities = [];
 29→
 30→    public ColliderDebugSystem(World world)
 31→    {
 32→        _world = world;
 33→        _colliderEntities = world.GetEntities()
 34→            .With<ColliderTag>()
 35→            .With<Transform>()
 36→            .AsSet();
 37→    }
 38→
 39→    public bool IsEnabled { get; set; } = true;
 40→
 41→    public void Update(GameState state)
 42→    {
 43→        foreach (var entity in _debugEntities)
 44→        {
 45→            if (entity.IsAlive)
 46→                entity.Dispose();
 47→        }
 48→        _debugEntities.Clear();
 49→
 50→        if (!IsEnabled || !Enabled) return;
 51→
 52→        foreach (var entity in _colliderEntities.GetEntities())
 53→        {
 54→            ref readonly var transform = ref entity.Get<Transform>();
 55→
 56→            if (entity.Has<BoxCollider>())
 57→            {
 58→                ref readonly var box = ref entity.Get<BoxCollider>();
 59→                CreateBoxOutline(transform, box);
 60→            }
 61→
 62→            if (entity.Has<ConvexCollider>())
 63→            {
 64→                var convex = entity.Get<ConvexCollider>();
 65→                CreateConvexOutline(convex);
 66→            }
 67→        }
 68→    }
 69→
 70→    private void CreateBoxOutline(in Transform transform, in BoxCollider box)
 71→    {
 72→        var color = GetDebugColor(box);
 73→
 74→        var topLeft = new Vector2(
 75→            transform.WorldPosition.X + box.Bounds.Left,
 76→            transform.WorldPosition.Y + box.Bounds.Top);
 77→        var topRight = new Vector2(
 78→            transform.WorldPosition.X + box.Bounds.Right,
 79→            transform.WorldPosition.Y + box.Bounds.Top);
 80→        var bottomRight = new Vector2(
 81→            transform.WorldPosition.X + box.Bounds.Right,
 82→            transform.WorldPosition.Y + box.Bounds.Bottom);
 83→        var bottomLeft = new Vector2(
 84→            transform.WorldPosition.X + box.Bounds.Left,
 85→            transform.WorldPosition.Y + box.Bounds.Bottom);
 86→
 87→        var vertices = new List<VertexPositionColor>();
 88→        var indices = new List<int>();
 89→        int indexOffset = 0;
 90→
 91→        LineMeshGenerator.AddLine(vertices, indices, topLeft, topRight, LineThickness, color, ref indexOffset);
 92→        LineMeshGenerator.AddLine(vertices, indices, topRight, bottomRight, LineThickness, color, ref indexOffset);
 93→        LineMeshGenerator.AddLine(vertices, indices, bottomRight, bottomLeft, LineThickness, color, ref indexOffset);
 94→        LineMeshGenerator.AddLine(vertices, indices, bottomLeft, topLeft, LineThickness, color, ref indexOffset);
 95→
 96→        CreateDebugEntity(vertices, indices);
 97→    }
 98→
 99→    private void CreateConvexOutline(ConvexCollider convex)
100→    {
101→        var color = GetDebugColor(convex);
102→        var verts = convex.WorldVertices;
103→        if (verts == null || verts.Length < 3) return;
104→
105→        var vertices = new List<VertexPositionColor>();
106→        var indices = new List<int>();
107→        int indexOffset = 0;
108→
109→        for (int i = 0; i < verts.Length; i++)
110→        {
111→            var start = verts[i];
112→            var end = verts[(i + 1) % verts.Length];
113→            LineMeshGenerator.AddLine(vertices, indices, start, end, LineThickness, color, ref indexOffset);
114→        }
115→
116→        CreateDebugEntity(vertices, indices);
117→    }
118→
119→    private void CreateDebugEntity(List<VertexPositionColor> vertices, List<int> indices)
120→    {
121→        var entity = _world.CreateEntity();
122→        _debugEntities.Add(entity);
123→
124→        entity.Set(new DrawComponent
125→        {
126→            Type = DrawElementType.Mesh,
127→            Vertices = vertices.ToArray(),
128→            Indices = indices.ToArray(),
129→            PrimitiveType = PrimitiveType.TriangleList,
130→            Target = RenderTargetID.Main,
131→            LayerDepth = DebugLayerDepth
132→        });
133→        entity.Set<Visible>();
134→    }
135→
136→    private static Color GetDebugColor(ICollider collider)
137→    {
138→        if (!collider.Enabled) return Color.Gray;
139→        return collider.Passive ? Color.Green : Color.Red;
140→    }
141→
142→    public void Dispose()
143→    {
144→        foreach (var entity in _debugEntities)
145→        {
146→            if (entity.IsAlive)
147→                entity.Dispose();
148→        }
149→        _debugEntities.Clear();
150→        _colliderEntities.Dispose();
151→    }
152→}
